/// A pure specification function over immutable sequences.
/// Given a non‐empty sequence `xs` and a (possibly large) rotation amount `n`,
/// returns the sequence rotated to the right by `n mod xs.len()`.
#[verifier::spec]
fn seq_rotate_right<T: Copy>(xs: Seq<T>, n: nat) -> Seq<T> {
    // precondition: the sequence must be non‐empty
    requires(xs.len() > 0);
    let len = xs.len();
    let m = n % len;         // effective rotation
    let s = len - m;         // split index
    // result is suffix xs[s..len] followed by prefix xs[0..s]
    xs.subrange(s, len) + xs.subrange(0, s)
}

